start
if (Current Attempt still queued?) then (yes)
 :recovery_v1.repair_work(factory, ...);
 :lock_pair; current + queued + dispatch due checks;
 if (work outbox row missing?) then (yes)
  :stage stable work_message_id(attempt_id,state_version)\nwith short_lane.work_lane;
 else (row exists)
  if (sent_at set and claim_token is None?) then (yes)
   :next_try_at=DB now (rearm same row);
  else (unsent / being published)
   :leave row to publisher;
  endif
 endif
 :commit; publish_outbox -> SQS;\nAttempt stays queued with same UUID;
else (claimed encoder stopped renewing)
 :recovery.recover_expired or matched terminal_event;
 :interrupt under Job lock;\nAttempt=abandoned; Job=failed; cleanup + result outbox;
 :commit; Processing relay publishes failed result;\nMedia commits failed projection;
 :owner retry -> new Attempt + work/result outbox;
endif
stop
legend bottom
